/** Actual fuel/steam rotary alloying and molten pouring. This source machine has no HE interface. */
public final class RotaryFurnaceEntity extends ThermalMachine implements StandardFluidTransceiver,IFluidCopiable ,com.hbm.multiblock.proxy.SourceProxyInventoryAccess {
 public static Consumer<RotaryFurnaceEntity> CLIENT_TICK=ignored->{};
 public final FluidTank[] tanks={new FluidTank(HbmFluids.NONE,16000),new FluidTank(HbmFluids.STEAM,12000),new FluidTank(HbmFluids.SPENTSTEAM,120)};
 public final FluidTank smoke=new FluidTank(HbmFluids.SMOKE,50),leaded=new FluidTank(HbmFluids.SMOKE_LEADED,50),poison=new FluidTank(HbmFluids.SMOKE_POISON,50);
 public boolean isProgressing,isVenting,tilted;public float progress;public int burnTime,maxBurnTime,steamUsed,anim,lastAnim;public double burnHeat=1D;public MaterialStack output;
 private final Map<String,FluidPorts> groups=new HashMap<>();private final Map<String,List<Port>> activeGroups=new HashMap<>();private CompoundTag lastSent;
 private final FluidGroup steamGroup=new FluidGroup(new FluidTank[]{tanks[1]},new FluidTank[]{tanks[2]}),fluidGroup=new FluidGroup(new FluidTank[]{tanks[0]},FluidTank.EMPTY_ARRAY),smokeGroup=new FluidGroup(FluidTank.EMPTY_ARRAY,new FluidTank[]{smoke,leaded,poison});
 public RotaryFurnaceEntity(BlockPos pos,BlockState state){super(RotaryFurnaceContent.ENTITY.get(),pos,state,5);}
 @Override protected String title(){return "container.machineRotaryFurnace";}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new RotaryFurnaceMenu(id,inventory,this,worldPosition);}@Override public void writeClientSideData(AbstractContainerMenu menu,net.minecraft.network.RegistryFriendlyByteBuf buffer){buffer.writeBlockPos(worldPosition);}
 public static int maxOutput(){return HbmMaterials.shape("BLOCK").q(16);}public record Port(BlockPos position,Direction side){NodeConnection connection(){return new NodeConnection(position.relative(side),side);}}
 private static ForgeDirection source(Direction direction){return ForgeDirection.getOrientation(direction.get3DDataValue());}public static Direction turnDown(Direction facing){return source(facing).getRotation(ForgeDirection.DOWN).nativeDirection();}
 /** Exact rotatePorts source rows, including two outward faces sharing the same corner. */
 public static List<Port> blockPorts(BlockPos core,Direction facing){var dir=source(facing);var rot=dir.getRotation(ForgeDirection.UP);var result=new ArrayList<Port>();for(var p:new int[][]{{-2,0,-1,2},{-1,0,-1,2},{0,0,-1,2},{1,0,-1,2},{2,0,-1,2},{-1,4,0,1},{-2,0,-1,4},{-2,0,1,4}}){var face=ForgeDirection.getOrientation(p[3]);int fx=face.offsetX*rot.offsetX+face.offsetZ*dir.offsetX,fz=face.offsetX*rot.offsetZ+face.offsetZ*dir.offsetZ;Direction side=face.offsetY!=0?face.nativeDirection():Direction.fromDelta(fx,0,fz);result.add(new Port(core.offset(p[0]*rot.offsetX+p[2]*dir.offsetX,p[1],p[0]*rot.offsetZ+p[2]*dir.offsetZ),Objects.requireNonNull(side)));}return List.copyOf(result);}
 public static List<Port> steamPorts(BlockPos core,Direction facing){var rot=turnDown(facing);return List.of(new Port(core.relative(facing,-1).relative(rot,-2),facing.getOpposite()),new Port(core.relative(facing,-1).relative(rot,-1),facing.getOpposite()));}
 public static List<Port> fluidPorts(BlockPos core,Direction facing){var rot=turnDown(facing);return List.of(new Port(core.relative(facing).relative(rot,2),rot),new Port(core.relative(facing,-1).relative(rot,2),rot));}
 public static List<Port> smokePorts(BlockPos core,Direction facing){return List.of(new Port(core.relative(turnDown(facing)).above(4),Direction.UP));}
 public int[] accessibleSlots(BlockPos position,Direction side){var facing=DummyableBlock.facing(getBlockState());var rot=source(facing).getRotation(ForgeDirection.UP).nativeDirection();if(side==facing.getOpposite()){if(position.equals(worldPosition.relative(facing,-1).relative(rot,-2)))return new int[]{0};if(position.equals(worldPosition.relative(facing,-1).relative(rot,-1)))return new int[]{1};if(position.equals(worldPosition.relative(facing,-1)))return new int[]{2};}if(side==facing&&position.equals(worldPosition.relative(facing).relative(rot,-1)))return new int[]{4};return new int[0];}
 public RotaryFurnaceRecipe matchingRecipe(){if(level==null)return null;for(var recipe:RotaryFurnaceRecipes.recipes(level.getRecipeManager()))if(recipe.accepts(tanks[0].getTankType(),slots.get(0),slots.get(1),slots.get(2)))return recipe;return null;}
 public static void tick(Level level,BlockPos pos,BlockState state,RotaryFurnaceEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);else CLIENT_TICK.accept(machine);}
 private void serverTick(ServerLevel server){updatePorts(server);tanks[0].setType(3,slots.toArray(ItemStack[]::new));pour(server);var recipe=matchingRecipe();isProgressing=false;if(recipe!=null){if(burnTime<=0&&!slots.get(4).isEmpty()&&slots.get(4).getBurnTime(RecipeType.SMELTING)>0){burnHeat=RotaryFurnaceConfig.BURN.getMod(slots.get(4),RotaryFurnaceConfig.BURN.getModHeat());maxBurnTime=burnTime=RotaryFurnaceConfig.BURN.getBurnTime(slots.get(4))/2;removeItem(4,1);setChanged();}float speed=Math.max((float)burnHeat,1),steamMult=(float)(10*Math.log10(speed)+1);int[] consumed=recipe.consumed(slots.get(0),slots.get(1),slots.get(2));double rate=OreProcessing.rate(new ItemStack[]{slots.get(0),slots.get(1),slots.get(2)},consumed);if(canProcess(recipe,steamMult,rate)){progress+=speed/recipe.duration();tanks[1].setFill((int)(tanks[1].getFill()-recipe.steam()*steamMult));steamUsed+=recipe.steam()*steamMult;isProgressing=true;if(progress>=1F){progress-=1F;for(int i=0;i<3;i++)if(consumed[i]>0)removeItem(i,consumed[i]);if(!recipe.inputFluids().isEmpty())tanks[0].setFill(tanks[0].getFill()-recipe.inputFluids().getFirst().fill);int amount=OreProcessing.count(recipe.molten().amount,rate,server.random);if(output==null)output=new MaterialStack(recipe.molten().material,amount);else output.amount+=amount;setChanged();}if(burnTime>0){pollute(server,PollutionSystem.SOOT_PER_SECOND/10F);burnTime--;}}else progress=0;if(steamUsed>=100){int steamReturn=steamUsed/100,room=tanks[2].getMaxFill()-tanks[2].getFill(),doesReturn=Math.min(steamReturn,room);steamUsed-=doesReturn*100;tanks[2].setFill(tanks[2].getFill()+doesReturn);}}else progress=0;
  // Original vent() sets this during pollute(), but updateEntity resets it before serialize(). Keep that ordering.
  isVenting=false;var state=getUpdateTag(server.registryAccess());if(!state.equals(lastSent)||server.getGameTime()%20==0){lastSent=state;sync(50);}setChanged();}
 private boolean canProcess(RotaryFurnaceRecipe recipe,float steamMult,double rate){if(burnTime<=0)return false;if(!recipe.inputFluids().isEmpty()){var fluid=recipe.inputFluids().getFirst();if(tanks[0].getTankType()!=fluid.type||tanks[0].getFill()<fluid.fill)return false;}if(tanks[1].getFill()<recipe.steam()*steamMult)return false;if(tanks[2].getMaxFill()-tanks[2].getFill()<recipe.steam()*steamMult/100)return false;if(steamUsed>100)return false;if(output!=null&&(output.material!=recipe.molten().material||(long)output.amount+OreProcessing.maximumCount(recipe.molten().amount,rate)>maxOutput()))return false;return true;}
 private void pour(ServerLevel server){if(output==null)return;int previous=output.amount;var rot=turnDown(DummyableBlock.facing(getBlockState()));Vec3[] impact={Vec3.ZERO};output=FoundryPouring.pourSingleStack(server,worldPosition.getX()+.5+rot.getStepX()*2.875,worldPosition.getY()+1.25,worldPosition.getZ()+.5+rot.getStepZ()*2.875,6,true,output,HbmMaterials.shape("INGOT").q(1),impact);if(previous!=output.amount){var point=new Vec3(worldPosition.getX()+.5+rot.getStepX()*2.875,worldPosition.getY()+.75,worldPosition.getZ()+.5+rot.getStepZ()*2.875);float length=Math.max(1F,worldPosition.getY()+1-(float)(Math.ceil(impact[0].y)-1.125));PacketDistributor.sendToPlayersNear(server,null,worldPosition.getX()+.5,worldPosition.getY()+1,worldPosition.getZ()+.5,50,new FoundryStreamPacket(point.x,point.y,point.z,output.material.moltenColor(),rot,length,.625F,.625F));setChanged();}if(output.amount<=0)output=null;}
 private void pollute(ServerLevel server,float amount){smoke.setFill(smoke.getFill()+(int)Math.ceil(amount*100));if(smoke.getFill()>smoke.getMaxFill()){int overflow=smoke.getFill()-smoke.getMaxFill();smoke.setFill(smoke.getMaxFill());PollutionSystem.increment(server,worldPosition,PollutionType.SOOT,overflow/100F);isVenting=true;}}
 private void updateGroup(ServerLevel server,String name,List<Port> ports,FluidGroup owner){var active=ports.stream().filter(p->server.hasChunkAt(p.position)&&server.getBlockState(p.position).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(p.position))).toList();if(!active.equals(activeGroups.get(name))){var old=groups.remove(name);if(old!=null)old.remove(server);activeGroups.put(name,active);if(!active.isEmpty())groups.put(name,new FluidPorts(active.stream().map(Port::position).distinct().toArray(BlockPos[]::new),active.stream().map(Port::connection).toArray(NodeConnection[]::new)));}var group=groups.get(name);if(group!=null)group.update(server,owner);}
 private void updatePorts(ServerLevel server){var facing=DummyableBlock.facing(getBlockState());updateGroup(server,"steam",steamPorts(worldPosition,facing),steamGroup);updateGroup(server,"process",fluidPorts(worldPosition,facing),fluidGroup);updateGroup(server,"smoke",smokePorts(worldPosition,facing),smokeGroup);}
 private final class FluidGroup implements StandardFluidTransceiver{final FluidTank[] in,out;FluidGroup(FluidTank[] in,FluidTank[] out){this.in=in;this.out=out;}@Override public FluidTank[] getAllTanks(){var all=new ArrayList<FluidTank>();all.addAll(Arrays.asList(in));all.addAll(Arrays.asList(out));return all.toArray(FluidTank[]::new);}@Override public FluidTank[] getReceivingTanks(){return in;}@Override public FluidTank[] getSendingTanks(){return out;}@Override public boolean isLoaded(){return RotaryFurnaceEntity.this.isLoaded();}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long left=StandardFluidTransceiver.super.transferFluid(type,pressure,amount);if(left!=amount)setChanged();return left;}@Override public void useUpFluid(HbmFluidType type,int pressure,long amount){StandardFluidTransceiver.super.useUpFluid(type,pressure,amount);if(amount!=0)setChanged();}}
 @Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(HbmFluidType type,Direction side){return side!=null;}@Override public FluidTank[] getAllTanks(){return new FluidTank[]{tanks[0],tanks[1],tanks[2],smoke};}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{tanks[0],tanks[1]};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{tanks[2],smoke};}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long left=StandardFluidTransceiver.super.transferFluid(type,pressure,amount);if(left!=amount)setChanged();return left;}@Override public void useUpFluid(HbmFluidType type,int pressure,long amount){StandardFluidTransceiver.super.useUpFluid(type,pressure,amount);if(amount!=0)setChanged();}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){return slot<3||slot==4;}@Override public int[] getSlotsForFace(Direction side){return new int[0];}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return false;}@Override public List<TankView> tanks(){return Arrays.stream(getAllTanks()).map(t->new TankView(t.getTankType(),t.getFill(),t.getMaxFill())).toList();}@Override public List<ProgressView> progressBars(){var bars=new ArrayList<ProgressView>();bars.add(new ProgressView("gui.hbm.rotary_furnace.progress",progress,1,0x71c78b));bars.add(new ProgressView("gui.hbm.rotary_furnace.fuel",burnTime,maxBurnTime,0xe09d3c));if(output!=null)bars.add(new ProgressView(output.material.descriptionId(),output.amount,maxOutput(),output.material.moltenColor()));return bars;}
 private void materialWrite(CompoundTag tag){if(output!=null){tag.putInt("outType",output.material.id());tag.putInt("outAmount",output.amount);}}private void materialRead(CompoundTag tag){output=tag.contains("outType")?new MaterialStack(Objects.requireNonNull(HbmMaterials.byId(tag.getInt("outType"))),tag.getInt("outAmount")):null;}
 @Override protected void saveMachine(CompoundTag tag){for(int i=0;i<3;i++)tanks[i].writeToNBT(tag,"t"+i);smoke.writeToNBT(tag,"smoke0");leaded.writeToNBT(tag,"smoke1");poison.writeToNBT(tag,"smoke2");tag.putFloat("prog",progress);tag.putInt("burn",burnTime);tag.putDouble("heat",burnHeat);tag.putInt("maxBurn",maxBurnTime);tag.putBoolean("tilted",tilted);materialWrite(tag);}
 @Override protected void loadMachine(CompoundTag tag){for(int i=0;i<3;i++)tanks[i].readFromNBT(tag,"t"+i);smoke.readFromNBT(tag,"smoke0");leaded.readFromNBT(tag,"smoke1");poison.readFromNBT(tag,"smoke2");progress=tag.getFloat("prog");burnTime=tag.getInt("burn");burnHeat=tag.getDouble("heat");maxBurnTime=tag.getInt("maxBurn");tilted=tag.getBoolean("tilted");materialRead(tag);}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);if(!tag.contains("CustomName")&&tag.contains("name",Tag.TAG_STRING)&&!tag.getString("name").isEmpty())setCustomName(net.minecraft.network.chat.Component.literal(tag.getString("name")));}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);if(tag.contains("CustomName"))tag.putString("name",getDisplayName().getString());}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();for(int i=0;i<3;i++)tanks[i].writeToNBT(tag,"t"+i);tag.putBoolean("muffled",isMuffled());tag.putBoolean("tilted",tilted);tag.putBoolean("isVenting",isVenting);tag.putBoolean("isProgressing",isProgressing);tag.putFloat("prog",progress);tag.putInt("burn",burnTime);tag.putInt("maxBurn",maxBurnTime);materialWrite(tag);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){for(int i=0;i<3;i++)tanks[i].readFromNBT(tag,"t"+i);setMuffled(tag.getBoolean("muffled"));tilted=tag.getBoolean("tilted");isVenting=tag.getBoolean("isVenting");isProgressing=tag.getBoolean("isProgressing");progress=tag.getFloat("prog");burnTime=tag.getInt("burn");maxBurnTime=tag.getInt("maxBurn");materialRead(tag);}
 private void disconnect(){if(level instanceof ServerLevel server)groups.values().forEach(p->p.remove(server));groups.clear();activeGroups.clear();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}@Override public void setRemoved(){disconnect();super.setRemoved();}

 @Override public int[] sourceProxySlots(net.minecraft.core.BlockPos position,net.minecraft.core.Direction side){return accessibleSlots(position,side);}
}
